var n=`0982-samgyetang`;var t=`world-0982`;var a=`KR`;var s=`east-asia`;var r=4;var g=174;var d={en:`Samgyetang`,ua:`Самгєтан`};var o={en:`Samgyetang is a South Korea dish made with glutinous rice, whole chicken, garlic, dried date. This home-scale recipe assigns measured ingredients to the steps where they are used. Ginger and dates replace ginseng and jujubes; this is a simplified samgyetang, not an exact herbal soup.`,ua:`Самгєтан, страва кухні країни Південна Корея. Основні складники: клейкий рис, ціла курка, часник, сушений фінік. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Імбир і фініки замінюють женьшень та ююбу; це спрощений самгєтан, а не повністю автентичний цілющий суп.`};var h=[{en:`Soak the listed rice, grains or noodles in clean water for about 60 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 60 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`rice-soaking`],m:60,i:[[`glutinous-rice`,165,`g`],[`water`,440,`ml`]]},{en:`Stuff the rinsed whole chicken with the drained glutinous rice, garlic, ginger and dates; secure the opening with a skewer.`,ua:`Наповніть промиту цілу курку зцідженим клейким рисом, часником, імбиром та фініками; закріпіть отвір шпажкою.`,t:[`stuffing-vegetables`],m:15,i:[[`whole-chicken`,1.5,`kg`],[`garlic`,7,`clove`],[`ground-ginger`,35,`g`],[`dried-date`,7,`pcs`]]},{en:`Cover the stuffed chicken with water, add ginger and green onions, then gently boil until both chicken and the rice inside are completely cooked; check the meat reaches 74°C.`,ua:`Залийте фаршировану курку водою, додайте імбир і зелену цибулю та варіть до повної готовності курки й рису всередині; температура м’яса має сягнути 74°C.`,t:[`simmering`,`skimming-foam`],m:95,i:[[`water`,1850,`ml`],[`ground-ginger`,30,`g`],[`green-onion`,65,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]}];var c={slug:n,id:t,country:`KR`,region:s,servings:4,minutes:174,title:d,text:o,steps:h};export{a as country,c as default,t as id,g as minutes,s as region,r as servings,n as slug,h as steps,o as text,d as title};